class ModelNew(nn.Module):
    """
    Tanh activation implemented as a hand-written PTX kernel, launched through
    cutegen.ptx_runtime.PtxModule (no CUDA C++/CuTe/CUTLASS/Triton involved).

    Optimization applied: converted the kernel to a persistent grid-stride
    loop over 128-bit vectorized (v4) chunks. Instead of launching one thread
    per 4-element chunk (which for large tensors produced an extremely large
    grid, ~524288 blocks, and left achieved occupancy below theoretical due to
    scheduling/launch overhead), the kernel now launches a capped number of
    CTAs and each thread iterates over multiple vector chunks with a
    grid-stride loop. This reduces block-launch overhead while keeping the
    GPU fully saturated for this memory-bound kernel, and preserves identical
    numerical behavior (same fast-tanh approximation) and correct handling of
    tail elements.
    """

    def __init__(self):
        super().__init__()
        self._module = None

    def _get_module(self):
        if self._module is None:
            self._module = PtxModule(PTX_SOURCE)
        return self._module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "x must be a CUDA tensor"
        assert x.dtype == torch.float32, "x must be float32"

        x_c = x.contiguous()
        y = torch.empty_like(x_c)

        n = x_c.numel()

        vec_size = 4
        threads = 128

        n_vec_groups = n // vec_size
        needed_blocks = max(1, (n_vec_groups + threads - 1) // threads) if n_vec_groups > 0 else 1

        # Cap the grid size: with a grid-stride loop we don't need one thread
        # per vector-group; a modest number of persistent CTAs is enough to
        # saturate the GPU while avoiding excessive launch/scheduling overhead
        # for very large tensors.
        # Launch a grid sized to a whole number of "waves" across the GPU's
        # SMs instead of an arbitrary large cap. The grid-stride loop already
        # covers all elements regardless of grid size, so choosing a grid that
        # is an exact multiple of (SM count * blocks-per-SM at this occupancy)
        # avoids a partial trailing wave of thread blocks, which the profiler
        # identified as accounting for up to ~50% of the kernel's runtime.
        props = torch.cuda.get_device_properties(x_c.device)
        sm_count = props.multi_processor_count
        # With 128 threads/block and 40 registers/thread, sm_89 (Ada) allows
        # 12 resident blocks per SM (1536 max threads/SM // 128), matching the
        # kernel's measured 100% theoretical occupancy. However, launching
        # exactly one full "wave" of blocks (sm_count * blocks_per_sm) leaves
        # the hardware scheduler no flexibility to rebalance work: every CTA
        # is resident simultaneously and the whole kernel must wait for the
        # single slowest SM to retire its blocks (profiler showed 86.4%
        # achieved vs 100% theoretical occupancy, i.e. inter-block/SM load
        # imbalance). Instead, launch several such waves worth of smaller
        # per-block grid-stride work; as soon as an early block retires on a
        # given SM the scheduler immediately issues a new resident block from
        # the queue, letting faster SMs absorb more waves and naturally
        # smoothing out scheduling/launch imbalance across SMs without
        # changing any kernel semantics (same grid-stride tanh computation).
        blocks_per_sm = 12
        num_waves = 4
        full_wave_blocks = max(1, sm_count * blocks_per_sm * num_waves)
        blocks = min(needed_blocks, full_wave_blocks)

        module = self._get_module()
        stream = torch.cuda.current_stream()

        module.launch(
            "tanh_kernel",
            (blocks, 1, 1),
            (threads, 1, 1),
            [u64(x_c.data_ptr()), u64(y.data_ptr()), u64(n)],
            stream=stream,
        )

        return y


