    T reg[VecSize];
    #pragma unroll
    for (int i = 0; i < VecSize; ++i) {
      reg[i] = gX(i);
    }
    #pragma unroll
    for (int i = 0; i < VecSize; ++i) {
      float v = (float)reg[i];
      reg[i] = (T)tanhf(v);
    }
    #pragma unroll
    for (int i = 0; i < VecSize; ++i) {
      gY(i) = reg[i];
